        Instant lastExpiry = Instant.EPOCH;
        for (int i = 0; i < 10; i++) {
            lastExpiry = instant(placeOrder(item(productId, 3)).path("expiresAt"));
        }
        assertThat(product(productId).path("reserved").asInt()).isEqualTo(30);

