        assertThat(shipped.json().path("id").asLong()).isEqualTo(orderId);
        assertThat(shipped.json().path("paidAt").isNull()).isFalse();
        assertThat(order(orderId)).isEqualTo(shipped.json());

        Resp delivered = deliver(orderId);
